		httpStatus: RESPONSE_STATUS.NOT_FOUND,
		message: 'Route non trouvé',
		result: [],
	});
});
const port = process.env.PORT || 8000;

app.listen(port, async () => {
	// await db_async.sequelize.sync({ force: true });
