import React from 'react';
import { Link } from 'react-router-dom';
import { Film, Tv, Clock, Eye } from 'lucide-react';
import { MediaEntry } from '../../types';
import RatingStars from '../ui/RatingStars';

interface MediaCardProps {
	media: MediaEntry;
}

const MediaCard: React.FC<MediaCardProps> = ({ media }) => {
	const detailsPath =
		media.type === 'movie' ? `/movie/${media.id}` : `/tv/${media.id}`;

	return (
		<div className='card group h-full flex flex-col'>
			<div className='relative overflow-hidden'>
				<Link to={detailsPath}>
					<img
						src={media.poster}
						alt={media.title}
						className='w-full aspect-[2/3] object-cover transition-transform duration-300 group-hover:scale-105'
					/>
					<div className='absolute inset-0 bg-gradient-to-t from-gray-900 to-transparent opacity-70'></div>
					<div className='absolute top-2 left-2 bg-gray-900 bg-opacity-70 p-1 rounded'>
						{media.type === 'movie' ? (
							<Film className='h-4 w-4 text-blue-400' />
						) : (
							<Tv className='h-4 w-4 text-green-400' />
						)}
					</div>
					{media.progress !== undefined && media.progress < 100 && (
						<div className='absolute bottom-0 left-0 right-0 h-1 bg-gray-700'>
							<div
								className='h-full bg-blue-500'
								style={{ width: `${media.progress}%` }}
							></div>
						</div>
					)}
				</Link>
			</div>

			<div className='p-4 flex-grow flex flex-col'>
				<Link to={detailsPath}>
					<h3 className='font-medium text-lg line-clamp-2 group-hover:text-blue-400 transition-colors duration-200'>
						{media.title}
					</h3>
				</Link>

				<div className='flex items-center text-sm text-gray-400 mt-1 space-x-3'>
					<div className='flex items-center'>
						{media.type === 'movie' ? (
							<Film className='h-3 w-3 mr-1' />
						) : (
							<Tv className='h-3 w-3 mr-1' />
						)}
						<span>{media.type === 'movie' ? 'Movie' : 'TV'}</span>
					</div>

					{media.dateWatched && (
						<div className='flex items-center'>
							<Clock className='h-3 w-3 mr-1' />
							<span>{new Date(media.dateWatched).toLocaleDateString()}</span>
						</div>
					)}
				</div>

				<div className='mt-2'>
					<RatingStars rating={media.rating} readonly size='small' />
				</div>

				{media.status && (
					<div className='mt-2'>
						<span
							className={`px-2 py-1 text-xs rounded-full ${
								media.status === 'Currently Watching'
									? 'bg-blue-900 text-blue-200'
									: media.status === 'Completed'
									? 'bg-green-900 text-green-200'
									: media.status === 'Planning to Watch'
									? 'bg-purple-900 text-purple-200'
									: media.status === 'Paused'
									? 'bg-yellow-900 text-yellow-200'
									: 'bg-red-900 text-red-200'
							}`}
						>
							{media.status}
						</span>
					</div>
				)}

				<div className='mt-auto pt-3 flex justify-between items-center text-sm'>
					{media.rewatches > 0 && (
						<div className='flex items-center text-gray-400'>
							<Eye className='h-3 w-3 mr-1' />
							<span>
								{media.rewatches === 1
									? 'Watched once'
									: `Watched ${media.rewatches} times`}
							</span>
						</div>
					)}

					{media.favorite && (
						<span className='text-red-400 flex items-center'>
							<svg className='h-3 w-3 mr-1 fill-current' viewBox='0 0 24 24'>
								<path d='M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.54L12 21.35z' />
							</svg>
							Favorite
						</span>
					)}
				</div>
			</div>
		</div>
	);
};

export default MediaCard;

import React, { useState } from 'react';
import { X, Check } from 'lucide-react';
import { Movie, TvShow } from '../../types';
import RatingStars from '../ui/RatingStars';

interface AddReviewModalProps {
  media: Movie | TvShow;
  onClose: () => void;
  onSubmit: (rating: number, review: string, containsSpoilers: boolean) => void;
  initialRating?: number | null;
}

const AddReviewModal: React.FC<AddReviewModalProps> = ({ 
  media, 
  onClose, 
  onSubmit,
  initialRating = null 
}) => {
  const [rating, setRating] = useState<number>(initialRating || 0);
  const [review, setReview] = useState<string>('');
  const [containsSpoilers, setContainsSpoilers] = useState<boolean>(false);
  const [titleFocused, setTitleFocused] = useState<boolean>(false);
  const [reviewCharCount, setReviewCharCount] = useState<number>(0);

  const handleReviewChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    const text = e.target.value;
    setReview(text);
    setReviewCharCount(text.length);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (rating === 0) {
      alert('Please provide a rating before submitting.');
      return;
    }
    onSubmit(rating, review, containsSpoilers);
  };

  return (
    <div className="fixed inset-0 bg-black bg-opacity-75 z-50 flex items-center justify-center p-4 animate-fade-in">
      <div className="bg-gray-800 rounded-lg max-w-md w-full max-h-[90vh] overflow-y-auto">
        <div className="p-6">
          <div className="flex justify-between items-center mb-4">
            <h2 className="text-xl font-semibold">Write Your Review</h2>
            <button onClick={onClose} className="text-gray-400 hover:text-white">
              <X className="h-5 w-5" />
            </button>
          </div>

          <div className="flex items-start gap-4 mb-6">
            <img 
              src={media.poster} 
              alt={media.title} 
              className="w-16 rounded" 
            />
            <div>
              <h3 className="font-medium">{media.title}</h3>
              <p className="text-sm text-gray-400">{('releaseDate' in media) ? media.releaseDate : media.firstAirDate}</p>
            </div>
          </div>

          <form onSubmit={handleSubmit}>
            <div className="space-y-6">
              <div>
                <label className="block text-sm font-medium text-gray-300 mb-2">
                  Your Rating
                </label>
                <RatingStars rating={rating} onRatingChange={setRating} size="large" />
                {rating === 0 && (
                  <p className="text-sm text-red-400 mt-1">Please select a rating</p>
                )}
              </div>

              <div>
                <div className="flex justify-between mb-2">
                  <label className="block text-sm font-medium text-gray-300">
                    Your Review
                  </label>
                  <span className={`text-xs ${reviewCharCount > 1000 ? 'text-red-400' : 'text-gray-400'}`}>
                    {reviewCharCount}/1000
                  </span>
                </div>
                <div 
                  className={`border rounded-md transition-all duration-200 ${
                    titleFocused 
                      ? 'border-blue-500 ring-1 ring-blue-500' 
                      : 'border-gray-600'
                  }`}
                >
                  <textarea
                    value={review}
                    onChange={handleReviewChange}
                    onFocus={() => setTitleFocused(true)}
                    onBlur={() => setTitleFocused(false)}
                    className="w-full bg-gray-700 rounded-md px-3 py-2 text-white min-h-[150px] focus:outline-none"
                    placeholder="Share your thoughts about this title..."
                    maxLength={1000}
                  ></textarea>
                </div>
              </div>

              <div className="flex items-center">
                <input
                  type="checkbox"
                  id="spoilers"
                  checked={containsSpoilers}
                  onChange={(e) => setContainsSpoilers(e.target.checked)}
                  className="h-4 w-4 rounded border-gray-600 text-blue-600 focus:ring-blue-500 bg-gray-700"
                />
                <label htmlFor="spoilers" className="ml-2 text-sm text-gray-300">
                  This review contains spoilers
                </label>
              </div>
            </div>

            <div className="mt-6 flex space-x-3">
              <button
                type="button"
                onClick={onClose}
                className="flex-1 px-4 py-2 border border-gray-600 rounded-md text-white bg-transparent hover:bg-gray-700"
              >
                Cancel
              </button>
              <button
                type="submit"
                className="flex-1 px-4 py-2 bg-blue-600 rounded-md text-white flex items-center justify-center hover:bg-blue-700"
                disabled={rating === 0}
              >
                <Check className="mr-2 h-5 w-5" />
                Submit Review
              </button>
            </div>
          </form>
        </div>
      </div>
    </div>
  );
};

export default AddReviewModal;

